verus! {

    /// Given two vectors `arr1` and `arr2` of equal length, produces a new vector `result`
    /// of the same length such that, for each valid index `i`,
    /// result[i] == arr1[i] * arr2[i], and no 32-bit overflow or underflow occurs.
    ///
    /// Requires:
    ///  1. The two input vectors have the same length.
    ///  2. For each index `i` in bounds, the mathematical product of
    ///     `arr1[i]` and `arr2[i]` fits within the range [`i32::MIN`, `i32::MAX`].
    ///
    /// Ensures:
    ///  1. The result has the same length as the inputs.
    ///  2. For each index `i` in bounds, `result[i] == arr1[i] * arr2[i]`.
    fn element_wise_multiplication(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32>
        requires
            arr1.len() == arr2.len(),
            forall |i: usize|
                i < arr1.len() ==>
                let p: int = arr1[i].to_int() * arr2[i].to_int();
                p >= i32::MIN.to_int() && p <= i32::MAX.to_int(),
        ensures
            |result: Vec<i32>| result.len() == arr1.len()
                && forall |i: usize|
                    i < result.len() ==>
                    result[i].to_int() == arr1[i].to_int() * arr2[i].to_int()
    {
        // We'll build up the result vector one element at a time,
        // using a while loop with invariants to help the verifier.
        let len = arr1.len();
        let mut result: Vec<i32> = Vec::with_capacity(len);
        let mut i: usize = 0;

        while i < len
            invariant i <= len;
            invariant result.len() == i;
            invariant arr1.len() == len;
            invariant arr2.len() == len;
            invariant forall |j: usize|
                j < i ==>
                result[j].to_int() == arr1[j].to_int() * arr2[j].to_int();
            decreases len - i
        {
            let a = arr1[i];
            let b = arr2[i];
            // By the requires clause, a.to_int()*b.to_int() fits in an i32.
            assert(a.to_int() * b.to_int() >= i32::MIN.to_int());
            assert(a.to_int() * b.to_int() <= i32::MAX.to_int());
            // Safe to unwrap because of the above assertions.
            let prod: i32 = a.checked_mul(b).unwrap();
            result.push(prod);
            i += 1;
        }

        result
    }

} // end verus!